BEGIN;
CREATE SCHEMA IF NOT EXISTS relay_wonderland;
CREATE TABLE relay_wonderland.schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.players(player_id text PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.projects(project_id text PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}', version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.project_members(project_id text REFERENCES relay_wonderland.projects ON DELETE CASCADE, player_id text REFERENCES relay_wonderland.players ON DELETE CASCADE, role text NOT NULL, PRIMARY KEY(project_id,player_id));
CREATE TABLE relay_wonderland.agents(agent_id text PRIMARY KEY, owner_id text NOT NULL REFERENCES relay_wonderland.players, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.card_versions(card_version_id text PRIMARY KEY, agent_id text NOT NULL REFERENCES relay_wonderland.agents, owner_id text NOT NULL REFERENCES relay_wonderland.players, version integer NOT NULL CHECK(version>0), snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(agent_id,version));
CREATE TABLE relay_wonderland.mission_contracts(mission_id text PRIMARY KEY, project_id text NOT NULL REFERENCES relay_wonderland.projects, stage text NOT NULL, canonical_hash text NOT NULL, snapshot jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,canonical_hash));
CREATE TABLE relay_wonderland.challenges(challenge_id text PRIMARY KEY, project_id text NOT NULL REFERENCES relay_wonderland.projects, challenger_id text NOT NULL REFERENCES relay_wonderland.players, challenged_id text NOT NULL REFERENCES relay_wonderland.players, status text NOT NULL, snapshot jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(challenger_id<>challenged_id));
CREATE TABLE relay_wonderland.battles(battle_id text PRIMARY KEY, project_id text NOT NULL REFERENCES relay_wonderland.projects, mission_id text NOT NULL UNIQUE REFERENCES relay_wonderland.mission_contracts, mode text NOT NULL CHECK(mode IN ('GOAL','EVAL')), state text NOT NULL, snapshot jsonb NOT NULL, result jsonb, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.battle_participants(battle_id text REFERENCES relay_wonderland.battles ON DELETE CASCADE, player_id text REFERENCES relay_wonderland.players, agent_id text REFERENCES relay_wonderland.agents, card_version_id text REFERENCES relay_wonderland.card_versions, side smallint NOT NULL CHECK(side IN(1,2)), PRIMARY KEY(battle_id,player_id), UNIQUE(battle_id,side), UNIQUE(battle_id,agent_id));
CREATE TABLE relay_wonderland.execution_sessions(execution_id text PRIMARY KEY, battle_id text REFERENCES relay_wonderland.battles, mission_id text NOT NULL REFERENCES relay_wonderland.mission_contracts, project_id text NOT NULL REFERENCES relay_wonderland.projects, player_id text NOT NULL REFERENCES relay_wonderland.players, agent_id text NOT NULL REFERENCES relay_wonderland.agents, card_version_id text NOT NULL REFERENCES relay_wonderland.card_versions, state text NOT NULL, workspace_isolation_ref text NOT NULL, snapshot jsonb NOT NULL, checkpoint jsonb NOT NULL, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wonderland_execution_battle_state ON relay_wonderland.execution_sessions(battle_id,state);
CREATE TABLE relay_wonderland.provider_receipts(receipt_id text PRIMARY KEY, execution_id text NOT NULL REFERENCES relay_wonderland.execution_sessions ON DELETE CASCADE, provider_request_id text, receipt jsonb NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(execution_id,provider_request_id));
CREATE TABLE relay_wonderland.execution_usage(execution_id text PRIMARY KEY REFERENCES relay_wonderland.execution_sessions ON DELETE CASCADE, usage jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.presence(session_id text PRIMARY KEY, project_id text NOT NULL REFERENCES relay_wonderland.projects ON DELETE CASCADE, player_id text NOT NULL REFERENCES relay_wonderland.players ON DELETE CASCADE, snapshot jsonb NOT NULL, expires_at timestamptz NOT NULL, version bigint NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX wonderland_presence_expiry ON relay_wonderland.presence(project_id,expires_at);
CREATE TABLE relay_wonderland.entity_records(kind text NOT NULL CHECK(kind IN('PROJECT_BRAIN','PROJECT_AVATAR','GOAL_RESULT','EVAL_FINDING','REBUTTAL','GVE_EVIDENCE','SWARM','SUBAGENT','CARD_RECOMMENDATION','AGENT_STATISTICS','RATING')), record_id text NOT NULL, project_id text REFERENCES relay_wonderland.projects, battle_id text REFERENCES relay_wonderland.battles, owner_id text REFERENCES relay_wonderland.players, data jsonb NOT NULL, version bigint NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(kind,record_id));
CREATE INDEX wonderland_entity_scope ON relay_wonderland.entity_records(kind,project_id,battle_id);
CREATE TABLE relay_wonderland.rewards(grant_id text PRIMARY KEY, reward_key text NOT NULL UNIQUE, battle_id text NOT NULL REFERENCES relay_wonderland.battles, player_id text NOT NULL REFERENCES relay_wonderland.players, data jsonb NOT NULL, granted_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE relay_wonderland.inventory_grants(grant_id text PRIMARY KEY, grant_key text NOT NULL UNIQUE, player_id text NOT NULL REFERENCES relay_wonderland.players, battle_id text REFERENCES relay_wonderland.battles, item_id text NOT NULL, data jsonb NOT NULL, granted_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE relay_wonderland.artifacts(artifact_id text PRIMARY KEY, project_id text NOT NULL REFERENCES relay_wonderland.projects, owner_id text NOT NULL REFERENCES relay_wonderland.players, battle_id text REFERENCES relay_wonderland.battles, execution_id text REFERENCES relay_wonderland.execution_sessions, visibility text NOT NULL CHECK(visibility IN('OWNER','PARTICIPANTS','PUBLIC')), metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz);
CREATE INDEX wonderland_artifact_scope ON relay_wonderland.artifacts(project_id,owner_id,battle_id);
CREATE TABLE relay_wonderland.stream_sequences(stream_id text PRIMARY KEY, next_sequence bigint NOT NULL CHECK(next_sequence>0));
CREATE TABLE relay_wonderland.events(event_id text PRIMARY KEY, stream_id text NOT NULL, project_id text NOT NULL REFERENCES relay_wonderland.projects, sequence bigint NOT NULL CHECK(sequence>0), event_type text NOT NULL, visibility text NOT NULL, battle_id text REFERENCES relay_wonderland.battles, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(stream_id,sequence));
CREATE INDEX wonderland_event_replay ON relay_wonderland.events(project_id,sequence);
CREATE TABLE relay_wonderland.idempotency(scope text NOT NULL, command_id text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, PRIMARY KEY(scope,command_id));
INSERT INTO relay_wonderland.schema_migrations(version) VALUES('001_wonderland_runtime');
COMMIT;
